export const AOE_TYPES = {
  CIRCLE: 'circle',
  CONE: 'cone',
  CUBE: 'cube',
  LINE: 'line',
  SPHERE: 'sphere'
};

export const AOE_SIZES = {
  [AOE_TYPES.CIRCLE]: [5, 10, 15, 20, 30],
  [AOE_TYPES.CONE]: [15, 30, 60],
  [AOE_TYPES.CUBE]: [5, 10, 15, 20],
  [AOE_TYPES.LINE]: [20, 30, 60, 100, 120],
  [AOE_TYPES.SPHERE]: [5, 10, 15, 20, 30]
};

// Helper function to calculate affected cells based on AoE type and size
export const calculateAffectedCells = (centerPosition, type, size, gridSize = 20) => {
  const [centerRow, centerCol] = centerPosition.split('-').map(Number);
  const affectedCells = new Set();
  const cellSize = 5; // Each cell represents 5 feet
  const radius = size / cellSize;

  switch (type) {
    case AOE_TYPES.CIRCLE:
    case AOE_TYPES.SPHERE:
      for (let row = 0; row < gridSize; row++) {
        for (let col = 0; col < gridSize; col++) {
          const distance = Math.sqrt(
            Math.pow(row - centerRow, 2) + Math.pow(col - centerCol, 2)
          );
          if (distance <= radius) {
            affectedCells.add(`${row}-${col}`);
          }
        }
      }
      break;

    case AOE_TYPES.CONE:
      const coneLength = size / cellSize;
      for (let row = 0; row < gridSize; row++) {
        for (let col = 0; col < gridSize; col++) {
          const dx = col - centerCol;
          const dy = row - centerRow;
          const distance = Math.sqrt(dx * dx + dy * dy);
          if (distance <= coneLength) {
            const angle = Math.atan2(dy, dx) * (180 / Math.PI);
            if (angle >= -45 && angle <= 45) {
              affectedCells.add(`${row}-${col}`);
            }
          }
        }
      }
      break;

    case AOE_TYPES.CUBE:
      const halfSize = Math.floor(size / (2 * cellSize));
      for (let row = centerRow - halfSize; row <= centerRow + halfSize; row++) {
        for (let col = centerCol - halfSize; col <= centerCol + halfSize; col++) {
          if (row >= 0 && row < gridSize && col >= 0 && col < gridSize) {
            affectedCells.add(`${row}-${col}`);
          }
        }
      }
      break;

    case AOE_TYPES.LINE:
      const lineLength = size / cellSize;
      for (let i = 0; i <= lineLength; i++) {
        const row = centerRow;
        const col = centerCol + i;
        if (row >= 0 && row < gridSize && col >= 0 && col < gridSize) {
          affectedCells.add(`${row}-${col}`);
        }
      }
      break;
  }

  return Array.from(affectedCells);
};
